)

SELECT COUNT(*) cnt FROM (
SELECT reference_group_name||' → '||set_id||' = '||COUNT(*) k, determinant_type ctx FROM FND_SETID_ASSIGNMENTS GROUP BY reference_group_name, set_id, determinant_type
)

SELECT COUNT(*) cnt FROM (
SELECT iso_language_3 k, iso_language_2 ctx FROM FND_ISO_LANGUAGES_B
)

SELECT COUNT(*) cnt FROM (
SELECT language_code k, installed_flag ctx FROM FND_LANGUAGES_B WHERE installed_flag IN ('B','I')
)

SELECT COUNT(*) cnt FROM (
SELECT industry_code k, enabled_flag ctx FROM FND_INDUSTRIES_B WHERE enabled_flag='Y'
)

SELECT COUNT(*) cnt FROM (
SELECT language_code k, iso_territory ctx FROM FND_NATURAL_LANGUAGES_B WHERE enabled_flag='Y'
)

SELECT COUNT(*) cnt FROM (
SELECT timezone_code k, enabled_flag ctx FROM FND_TIMEZONES_B WHERE enabled_flag='Y'
)

SELECT COUNT(*) cnt FROM (
SELECT message_name k, application_id ctx FROM FND_MESSAGES_B WHERE created_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT lookup_type||'.'||lookup_code||' ('||enabled_flag||')' k, last_updated_by ctx FROM FND_LOOKUP_VALUES_B WHERE last_updated_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT o.profile_option_name||' ['||v.level_name||CASE WHEN v.level_name<>'SITE' THEN ':'||v.level_value END||'] = '||v.profile_option_value k, v.last_updated_by ctx FROM FND_PROFILE_OPTION_VALUES v JOIN FND_PROFILE_OPTIONS_B o ON o.profile_option_id=v.profile_option_id WHERE v.last_updated_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT o.profile_option_name||' ['||v.level_name||CASE WHEN v.level_name<>'SITE' THEN ':'||v.level_value END||'] = '||v.profile_option_value k, v.last_updated_by ctx FROM FND_PROFILE_OPTION_VALUES v JOIN FND_PROFILE_OPTIONS_B o ON o.profile_option_id=v.profile_option_id WHERE v.last_updated_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT value_set_code k, validation_type ctx FROM FND_VS_VALUE_SETS WHERE created_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT descriptive_flexfield_code||'.'||context_code||'.'||segment_code k, column_name ctx FROM FND_DF_SEGMENTS_B WHERE created_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT entity_name k, table_name ctx FROM FND_DOCUMENT_ENTITIES WHERE created_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT category_name k, NULL ctx FROM FND_DOCUMENT_CATEGORIES WHERE created_by<>'SEED_DATA_FROM_APPLICATION'
)

SELECT COUNT(*) cnt FROM (
SELECT o.profile_option_name||' ['||v.level_name||CASE WHEN v.level_name<>'SITE' THEN ':'||v.level_value END||'] = '||v.profile_option_value k, CASE WHEN v.last_updated_by='SEED_DATA_FROM_APPLICATION' THEN 'seed' ELSE v.last_updated_by END ctx FROM FND_PROFILE_OPTION_VALUES v JOIN FND_PROFILE_OPTIONS_B o ON o.profile_option_id=v.profile_option_id WHERE o.profile_option_name IN ('ORA_SVC_ENABLE_INBOUND_MSG_SR_TAG_PREDICTION','ORA_SVC_INBOUND_MSG_PREDICTION_THRESHOLD_FOR_SR_TAG','SVC_ENABLE_INBOUND_MSG_SR_CATEGORY_PREDICTION','SVC_ENABLE_INBOUND_MSG_SR_PRODUCT_PREDICTION','SVC_INBOUND_MSG_ATTRIBUTE_PREDICTION_INPUT','SVC_INBOUND_MSG_PREDICTION_THRESHOLD_FOR_SR_CATEGORY_ID','SVC_INBOUND_MSG_PREDICTION_THRESHOLD_FOR_SR_PRODUCT_ID')
)

SELECT COUNT(*) cnt FROM (
SELECT o.profile_option_name||' ['||v.level_name||CASE WHEN v.level_name<>'SITE' THEN ':'||v.level_value END||'] = '||v.profile_option_value k, CASE WHEN v.last_updated_by='SEED_DATA_FROM_APPLICATION' THEN 'seed' ELSE v.last_updated_by END ctx FROM FND_PROFILE_OPTION_VALUES v JOIN FND_PROFILE_OPTIONS_B o ON o.profile_option_id=v.profile_option_id WHERE o.profile_option_name IN ('SVC_ENABLE_SIMILAR_SR','SVC_SIMILAR_SR_ACCESS_TOKEN_URL','SVC_SIMILAR_SR_REST_ENDPOINT')
